import type { Register } from 'claude-code';
export const order: string[] = [];
export const A_FILE = '/tmp/twomods-a.txt';
// `$`-free: the caller hands in what it may do.
export async function startA(write: (path: string, text: string) => Promise<unknown>) { await write(A_FILE, 'a started'); }
export const register: Register = (on) => {
  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    order.push('a-in');
    const r = await next(e.name ? e : { ...e, name: 'FromA' });
    order.push('a-out');
    return r;
  });
};

files.hooks/b.tsx:
import type { Register } from 'claude-code';
import { order, startA } from './a.ts';
export const register: Register = (on) => {
  on('session.start', async ($, e, next) => {
    await startA((path, text) => $.fs.write(path, text));
    await $.fs.write('/tmp/twomods-b.txt', 'b started');
    return next(e);
  });
  on('tool.call', async ($, e, next) => {
    order.push('b-in');
    if (e.tool === 'Agent') await $.fs.write('/tmp/twomods-b-saw.txt', `b saw name=${(e as { name?: string }).name ?? 'none'} order=${order.join(',')}`);
    const r = await next(e);
    order.push('b-out');
    return r;
  });
};

